def find_cycle(adj, vertex):
    """Try to find a cycle passing through vertex using DFS"""
    stack = [(vertex, -1, [])]
    colors = {v: 0 for v in range(1, len(adj))}
    colors[vertex] = 1

    while stack:
        curr, parent_idx, path = stack.pop()

        for i, neighbor in enumerate(adj[curr]):
            if i == parent_idx:
