    # Find positions with -1 (1-indexed)
    missing_positions = []
    for i in range(n):
        if arr[i] == -1:
            missing_positions.append(i + 1)

    if not missing_positions:
        # No -1, only one configuration (the given one)
        # Check if it has any fixed points (shouldn't based on problem)
        return str(1)

    # Find missing values (values not present in permutation)
    fixed_values = set()
    for val in arr:
        if val != -1:
            fixed_values.add(val)

    missing_values = []
    for v in range(1, n + 1):
        if v not in fixed_values:
            missing_values.append(v)

    m = len(missing_positions)  # number of positions to fill
    missing_values_set = set(missing_values)

    # Count how many missing positions would create fixed points if matched directly
    # A position p creates a fixed point if p is in missing_values
    s = sum(1 for pos in missing_positions if pos in missing_values_set)

    MOD = 1000000007

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Precompute inverse factorials using Fermat's little theorem
    inv_fact = [1] * (m + 1)
    inv_fact[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    # Use inclusion-exclusion to count derangements
    # Formula: sum_{k=0}^{s} (-1)^k * C(s, k) * (m-k)!
    result = 0
    for k in range(s + 1):
        # C(s, k) = s! / (k! * (s-k)!)
        comb = fact[s] * inv_fact[k] % MOD * inv_fact[s - k] % MOD
        term = comb * fact[m - k] % MOD

        if k % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result)


