from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # Store edges as (u, v, w, 1-indexed index)
    edges = []
    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))

    # Build adjacency list without ignored edges
    def build_adj(ignored_indices):
        adj = [[] for _ in range(n + 1)]
        for idx, (u, v, w, eid) in enumerate(edges):
            if idx not in ignored_indices:
                adj[u].append((v, w))
                adj[v].append((u, w))
        return adj

    # BFS to check if t is reachable from s
    def is_connected(s, t, adj):
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, _ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Check single edge removals
    def check_single():
        if not is_connected(s, t, build_adj(set())):
            return 0, []  # Already disconnected

        best_w = float('inf')
        best_idx = None

        for idx, (u, v, w, eid) in enumerate(edges):
            if not is_connected(s, t, build_adj({idx})):
                if w < best_w:
                    best_w = w
                    best_idx = eid

        if best_idx is not None:
            return best_w, [best_idx]

    # Check all pairs of edge removals
    def check_pairs():
        if not is_connected(s, t, build_adj(set())):
            return 0, []

        best_w = float('inf')
        best_indices = None

        for i in range(len(edges)):
            for j in range(i + 1, len(edges)):
                ignored = {i, j}
                if not is_connected(s, t, build_adj(ignored)):
                    w1, w2 = edges[i][2], edges[j][2]
                    if w1 + w2 < best_w:
                        best_w = w1 + w2
                        best_indices = sorted([edges[i][3], edges[j][3]])
                        # Early termination since we want minimum
                        break
            if best_indices is not None:
                break

        if best_indices is not None:
            return best_w, best_indices

    # Check if already disconnected
    if not is_connected(s, t, build_adj(set())):
        return "0\n0\n"

    # Try single edge first
    result = check_single()
    if result[0] != float('inf'):
        return f"{result[0]}\n1\n{result[1][0]}\n"

    # Try pairs
    result = check_pairs()
    if result[0] != float('inf'):
        return f"{result[0]}\n2\n{result[1][0]} {result[1][1]}\n"

    return "-1\n"

