    for i in range(2, 2 + k):
        x, y = map(int, data[i].split())
        special_pairs.append((x, y))

    # Check if special pairs form a cycle
    # Each node can have at most one outgoing and one incoming edge in special pairs
    x_to_y = {}
    y_from_x = {}

    for x, y in special_pairs:
        if y in x_to_y:  # Two different x map to same y - impossible
            return '\n0\n'
        if x in y_from_x:  # Two different y map to same x - impossible
            return '\n0\n'
        x_to_y[x] = y
        y_from_x[y] = x

    # Check for cycles in special pairs using DFS
    def has_cycle():
        visited = [0] * (n + 1)  # 0: unvisited, 1: visiting, 2: visited
        for i in range(1, n + 1):
            if visited[i] == 0:
                # Check each starting point of a special pair
                start = None
                for x in range(1, n + 1):
                    if x in x_to_y:
                        start = x
                        break
                if start is not None:
                    stack = [start]
                    path = []
                    while stack:
                        node = stack.pop()
                        path.append(node)
                        if visited[node] == 1:
                            return True  # Cycle detected
                        if visited[node] == 2:
                            continue
                        visited[node] = 1
                        next_node = x_to_y.get(node)
                        if next_node:
                            if visited[next_node] == 0:
                                stack.append(next_node)
                        if node != start:  # Only check cycle if back to start
                            continue
                    visited[start] = 2
        return False

    # Also check more thoroughly - trace each path
    parent_in_special = x_to_y
    def detect_cycle_from(start):
        visited = set()
        current = start
        while current in parent_in_special:
            if current in visited:
                return True
            visited.add(current)
            current = parent_in_special[current]
        return False

    for start in range(1, n + 1):
        if start in parent_in_special:
            if detect_cycle_from(start):
                return '\n0\n'

    # Check if prerequisite graph is acyclic and find topological sort
    # In-degree in prerequisite graph (ignoring special pairs for now)
    indegree = [0] * (n + 1)
    adj = defaultdict(list)

    for i in range(1, n + 1):
        prereq = p[i - 1]
        if prereq != 0:
            adj[prereq].append(i)
            indegree[i] += 1

    # Build the final graph considering special pairs as edges too
    indegree_final = [0] * (n + 1)

    for i in range(1, n + 1):
        prereq = p[i - 1]
        if prereq != 0:
            indegree_final[i] += 1

    # Kahn's algorithm with special pair constraints
    # We need to find a valid topological order
    # Special pairs add immediate adjacency constraints

    # Let's find the root of prerequisite graph (no incoming edges)
    candidates = [i for i in range(1, n + 1) if indegree_final[i] == 0]

    if not candidates:
        return '\n0\n'

    # BFS topological sort
    queue = list(candidates)
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in adj[node]:
            indegree_final[neighbor] -= 1
            if indegree_final[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return '\n0\n'

    # Now verify special pairs are satisfied in result
    pos = {x: i for i, x in enumerate(result)}

    for x, y in special_pairs:
        if pos[y] == pos[x] + 1:
            continue
        else:
            return '\n0\n'

    # Convert positions to check if special pairs can be satisfied
    # Actually, the problem is more complex - we need to reorder

    # Build path following special pairs starting from candidates
    result = []
    remaining = set(range(1, n + 1))

    while remaining:
        start_candidates = [x for x in remaining if p[x - 1] == 0 or p[x - 1] not in remaining]

        if not start_candidates:
            return '\n0\n'

        start = start_candidates[0]
        result.append(start)
        remaining.remove(start)

        following = True
        while following and remaining:
            # Try to follow special pair from last result
            last = result[-1]
            if last in x_to_y:
                target = x_to_y[last]
                if target in remaining:
                    result.append(target)
                    remaining.remove(target)
                else:
                    following = False
            else:
                following = False

        if not following and remaining:
            # Need to find other valid starts
            # Find a node whose prerequisite is already in result
            valid_starts = []
            for node in remaining:
                if p[node - 1] in result:
                    if p[node - 1] != 0:
                        valid_starts.append(node)

            if not valid_starts:
                # This means no valid topological order exists with special pairs
                return '\n0\n'

            start = valid_starts[0]
            result.append(start)
            remaining.remove(start)

    # Check if all nodes are placed
    if len(result) != n:
        return '\n0\n'

    # Verify all prerequisites satisfied
    result_positions = {result[i]: i for i in range(n)}

    for node in range(1, n + 1):
        prereq = p[node - 1]
        if prereq != 0:
            if result_positions[prereq] >= result_positions[node]:
                return '\n0\n'

    # Verify special pairs
    for x, y in special_pairs:
        if result_positions[y] != result_positions[x] + 1:
            return '\n0\n'

    return '\n' + ' '.join(map(str, result)) + '\n'


