            if v != p:
                children[u].append(v)
                build_tree(v, u)

    build_tree(1, 0)

    # dp[u] = dict mapping component_size u belongs to -> maximum product
    # in the subtree rooted at u, where all other nodes in subtree
    # are optimally partitioned

    def solve(u):
        # Returns dict: component_size -> max_product

        # Base case: leaf node
        if not children[u]:
            return {1: 1}  # Just u itself, size 1, product 1

        dp_u = {1: 1}  # Start with just u

        for v in children[u]:
            child_dp = solve(v)
            new_dp = {}

            # For each possible state at u
            for size_u, prod_u in dp_u.items():
                # For each possible state at child v
                for size_v, prod_v in child_dp.items():
                    # Option 1: Cut edge (u,v) - v's component is independent
                    # We multiply products (independent components)
                    new_size = size_u
                    new_prod = prod_u * prod_v
                    if new_size in new_dp:
                        new_dp[new_size] = max(new_dp[new_size], new_prod)
                    else:
                        new_dp[new_size] = new_prod

                    # Option 2: Keep edge (u,v) - merge v's component into u's
                    new_size = size_u + size_v
                    new_prod = prod_u * prod_v
                    if new_size in new_dp:
                        new_dp[new_size] = max(new_dp[new_size], new_prod)
                    else:
                        new_dp[new_size] = new_prod

            dp_u = new_dp

        return dp_u

    result_dp = solve(1)
    result = max(result_dp.values())
    return str(result)

