    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[i+1].split()))
        a, b, e = parts
        edges.append((a, b, e))

    if m == n - 1:
        return ''

    edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))
    def find(x):
        root = x
        while parent[root] != root:
            parent[root] = parent[parent[root]]
            root = parent[root]
        return root
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_edges = []
    for a, b, e in edges:
        if union(a, b):
            mst_edges.append((a, b, e))

    adj = [[] for _ in range(n + 1)]
    for a, b, e in mst_edges:
        adj[a].append(b)
        adj[b].append(a)

    # BFS from node 1
    parent_arr = [0] * (n + 1)
    depth = [0] * (n + 1)
    order = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    parent_arr[1] = 1
    depth[1] = 0

    idx = 0
    while idx < len(order):
        u = order[idx]
        idx += 1
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent_arr[v] = u
                depth[v] = depth[u] + 1
                order.append(v)

    # Binary lifting
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    mn = [[0] * (n + 1) for _ in range(LOG)]

    for i in range(1, n + 1):
        up[0][i] = parent_arr[i]
        mn[0][i] = mn[0][up[0][i]] if up[0][i] != 0 and up[0][i] != i else 0

    for j in range(1, LOG):
        for i in range(1, n + 1):
            up[j][i] = up[j-1][up[j-1][i]]
            a, b = up[j-1][i], up[j-1][a]
            if a == b:
                mn[j][i] = mn[j-1][i]
            else:
                mn[j][i] = max(mn[j-1][i], mn[j-1][b])

    def lca(u, v):
        if u == v:
            return u
        if depth[u] < depth[v]:
            u, v = v, u

        for i in range(LOG):
            if (depth[u] - depth[v]) >> i & 1:
                v = up[i][v]

        if u == v:
            return u

        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                u = up[i][u]
                v = up[i][v]

        return up[0][u]

    res = []
    for i in range(m):
        a, b, e = edges[i]
        if not set(mst_edges, (a,b,e)):
            l = lca(a, b)
            ma = 0
            if depth[a] > depth[l]:
                for k in range(LOG):
                    if (depth[a] - depth[l]) >> k & 1:
                        ma = max(ma, mn[k][a])
                        a = up[k][a]
            if depth[b] > depth[l]:
                for k in range(LOG):
                    if (depth[b] - depth[l]) >> k & 1:
                        ma = max(ma, mn[k][b])
                        b = up[k][b]
            res.append(ma)

    return '\n'.join(map(str, res))

