    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def point_in_triangle(p, a, b, c):
        cp1 = cross_product(a, b, p)
        cp2 = cross_product(b, c, p)
        cp3 = cross_product(c, a, p)
        if cp1 == 0 and on_segment(p, a, b):
            return True
        if cp2 == 0 and on_segment(p, b, c):
            return True
        if cp3 == 0 and on_segment(p, c, a):
            return True
        if cp1 * cp2 > 0 and cp2 * cp3 > 0 and cp3 * cp1 > 0:
            return True
        return False

    def segment_intersect(p1, p2, p3, p4):
        d1 = cross_product(p3, p4, p1)
        d2 = cross_product(p3, p4, p2)
        d3 = cross_product(p1, p2, p3)
