        if d2 == 0 and on_segment(p2, p3, p4):
            return True
        if d3 == 0 and on_segment(p3, p1, p2):
            return True
        if d4 == 0 and on_segment(p4, p1, p2):
            return True
        return False

    def triangles_intersect(tri1, tri2):
        for i in range(3):
            for j in range(i + 1, 3):
                if point_in_triangle(tri2[j], tri1[0], tri1[i], tri1[(i+1)%3]):
