        for k in range(3):
            for m in range(k + 1, 3):
                if segment_intersect(tri1[k], tri1[m], tri2[0], tri2[(m+1)%3]):
                    return True
                if segment_intersect(tri1[k], tri1[m], tri2[(m+1)%3], tri2[m]):
                    return True
        return False

