    for i in range(n):
        grid.append(lines[i + 1] if i + 1 < len(lines) else "")

    # Directions: (row_change, col_change)
    # Based on button: U, D, L, R with possible swaps
    def get_moves(swap_lr, swap_ud):
        base_moves = {
            'U': (-1, 0),
            'D': (1, 0),
            'L': (0, -1),
            'R': (0, 1)
        }
        result = {}
        for move, (dr, dc) in base_moves.items():
            if move in ('L', 'R') and swap_lr:
                # Swap directions
                if move == 'L':
                    dr, dc = 0, 1
                else:
                    dr, dc = 0, -1
            if move in ('U', 'D') and swap_ud:
                # Swap directions
                if move == 'U':
                    dr, dc = 1, 0
                else:
                    dr, dc = -1, 0
            result[move] = (dr, dc)
        return result

