                    if (nr, nc) not in visited:
                        cell = grid[nr][nc]
                        if cell != '*':  # Avoid dangerous cells
                            visited.add((nr, nc))
                            queue.append(((nr, nc), path + move))
        return None

    # Try different configurations
    for swap_lr in [swap_LR, 0, 1]:
        for swap_ud in [swap_UD, 0, 1]:
            mapping = get_moves(swap_lr, swap_ud)
            result = bfs((0, 0), mapping)  # 0-indexed internally from (1,1)
            if result:
                return result + "\n"

    return ""

