def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse tree
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)

    # BFS to establish tree structure and processing order
    parent = [0] * (n + 1)
    order = []
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        node = queue.pop(0)
        order.append(node)
        for child in adj[node]:
            if not visited[child]:
                visited[child] = True
                parent[child] = node
                queue.append(child)

    ans = [0] * (n + 1)

    for k in range(1, n + 1):
        if k > n:
            ans[k] = 0
            continue

        if k == 1:
            ans[k] = n
            continue

        # DP: for each node, track [count, max_extension]
        # count = paths of length k completely in subtree
        # max_extension = longest path starting at this node going down

        count = [0] * (n + 1)
        ext = [0] * (n + 1)

        for i in range(n - 1, -1, -1):
            u = order[i]
            child_exts = []

            for child in adj[u]:
                if child != parent[u]:
                    child_exts.append(ext[child])

            if child_exts:
                ext[u] = 1 + max(child_exts)
            else:
                ext[u] = 0

            # Count paths
            for val in child_exts:
                if val + 1 == k:
                    count[u] += 1
                elif val + 1 < k:
                    # Could potentially be extended above u
                    pass

            # Add paths from children
            for child in adj[u]:
                if child != parent[u]:
                    count[u] += count[child]

        ans[k] = count[1]

    return '\n'.join(map(str, ans[1:]))


