def FenwickTreeBIT(n):
    self.n = n
    self.tree = [0] * (n + 1)

    def update(i, delta):
        i += 1  # 1-indexed
        while i < len(self.tree):
            self.tree[i] += delta
            i += i & (-i)

    def query(i):
        i += 1  # 1-indexed
        result = 0
        while i > 0:
            result += self.tree[i]
            i -= i & (-i)
        return result

    def range_query(l, r):
        return query(r) - query(l - 1)

    return type('BIT', (), {'update': update, 'query': query, 'range_query': range_query})

