                return "-1"
            t_x_in = float('-inf')
            t_x_out = float('inf')
        elif vx > 0:
            t_x_in = (x1 - rx) / vx
            t_x_out = (x2 - rx) / vx
        else:  # vx < 0
            t_x_in = (x2 - rx) / vx
            t_x_out = (x1 - rx) / vx

        # Calculate when this mouse enters/leaves for y
        if vy == 0:
            # Position doesn't change in y
            if not (y1 < ry < y2):
                return "-1"
            t_y_in = float('-inf')
            t_y_out = float('inf')
        elif vy > 0:
            t_y_in = (y1 - ry) / vy
            t_y_out = (y2 - ry) / vy
        else:  # vy < 0
            t_y_in = (y2 - ry) / vy
            t_y_out = (y1 - ry) / vy

        # Mouse is inside when BOTH x and y are in range
        t_in = max(t_x_in, t_y_in)
        t_out = min(t_x_out, t_y_out)

        # Valid interval is [t_in, t_out], need it to overlap with [0, inf)
        # and t_out must be > t_in strictly
        if t_out <= t_in:
            return "-1"

        # Also need at least some valid time >= 0
        if max(t_in, 0.0) >= t_out:
            return "-1"

        # Intersection of this mouse's valid interval with global constraints
        global_enter = max(global_enter, t_in)
        global_exit = min(global_exit, t_out)

        # Early exit if intervals no longer intersect
        if global_enter >= global_exit:
            return "-1"

    # Final check (in case exit is inf)
    if global_exit <= global_enter:
        return "-1"

    return str(global_enter)


