    parent = list(range(m + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Connect variables that appear together in the same clause
    for i in range(n):
        parts = lines[i + 1].split()
        k = int(parts[0])
        lits = [int(x) for x in parts[1:]]

        # Connect each pair of variables in this clause
        for j in range(len(lits)):
            for jj in range(j + 1, len(lits)):
                var1 = abs(lits[j])
                var2 = abs(lits[jj])
                if var1 != var2:
                    union(var1, var2)

    # Count connected components among variables that appear
    root_counts = {}
    for var in appearing_vars:
        root = find(var)
        root_counts[root] = root_counts.get(root, 0) + 1

    num_components = len(root_counts)

    # Answer is 2^(num_components + free_vars) mod MOD
    ans = pow(2, num_components + free_vars, MOD)

    return str(ans)

